struct HeavyData { ~HeavyData() { /* Cleanup happens here */ } };

// Exclusive Ownership (std::unique_ptr)
auto u_ptr = std::make_unique<HeavyData>();

// Cannot copy unique_ptr (move semantics required)
auto u_ptr_moved = std::move(u_ptr);

// Shared Ownership (std::shared_ptr)
auto s_ptr1 = std::make_shared<HeavyData>();
auto s_ptr2 = s_ptr1; // Reference count is 2

// Access underlying raw pointer (use sparingly)
HeavyData* raw = s_ptr1.get();

// Check count
long count = s_ptr1.use_count(); // 2

// Custom Deleter for unique_ptr (RAII for non-memory resources)
auto file_closer = [](FILE* f){ fclose(f); };
std::unique_ptr<FILE, decltype(file_closer)>
    log_file(fopen("log.txt", "w"), file_closer);
